function render() {
  var items = todos;
  var f = getFilter();
  // Build map of existing li elements by data-id
  var existing = {};
  var child = todoList.firstElementChild;
  while (child) {
    var id = Number(child.getAttribute('data-id'));
    existing[id] = child;
    child = child.nextElementSibling;
  }
  var idsSeen = {};
  var fragment = document.createDocumentFragment();
  for (var i = 0; i < items.length; i++) {
    var t = items[i];
    idsSeen[t.id] = true;
    var li;
    if (existing[t.id]) {
      // Reuse existing li element to preserve DOM references
      li = existing[t.id];
      delete existing[t.id];
      // Update class, style, and inner content
      var liClass = '';
      if (t.completed) {
        if (liClass) liClass += ' ';
        liClass += 'completed';
      }
      if (t.id === editingId) {
        if (liClass) liClass += ' ';
        liClass += 'editing';
      }
      li.className = liClass;
      var hidden = (f === 'active' && t.completed) || (f === 'completed' && !t.completed);
      li.style.display = hidden ? 'none' : '';
      // Update inner content
      var viewDiv = li.querySelector('.view');
      if (!viewDiv) {
        viewDiv = document.createElement('div');
        viewDiv.className = 'view';
        li.appendChild(viewDiv);
      }
      var toggle = viewDiv.querySelector('.toggle');
      if (!toggle) {
        toggle = document.createElement('input');
        toggle.className = 'toggle';
        toggle.type = 'checkbox';
        viewDiv.insertBefore(toggle, viewDiv.firstChild);
      }
      toggle.checked = t.completed;
      var label = viewDiv.querySelector('label');
      if (!label) {
        label = document.createElement('label');
        viewDiv.appendChild(label);
      }
      label.textContent = t.title;
      var destroy = viewDiv.querySelector('.destroy');
      if (!destroy) {
        destroy = document.createElement('button');
        destroy.className = 'destroy';
        viewDiv.appendChild(destroy);
      }
      var editInput = li.querySelector('.edit');
      if (!editInput) {
        editInput = document.createElement('input');
        editInput.className = 'edit';
        li.appendChild(editInput);
      }
      editInput.value = t.title;
    } else {
      // Create new li element
      var liClass = '';
      var hidden = false;
      if (t.completed) {
        if (liClass) liClass += ' ';
        liClass += 'completed';
      }
      if (t.id === editingId) {
        if (liClass) liClass += ' ';
        liClass += 'editing';
      }
      if (f === 'active' && t.completed) hidden = true;
      if (f === 'completed' && !t.completed) hidden = true;
      var html = '<li class="' + liClass + '" data-id="' + t.id + '"' + (hidden ? ' style="display:none"' : '') + '>';
      html += '<div class="view">';
      html += '<input class="toggle" type="checkbox"' + (t.completed ? ' checked' : '') + '>';
      html += '<label>' + escapeHtml(t.title) + '</label>';
      html += '<button class="destroy"></button>';
      html += '</div>';
      html += '<input class="edit" value="' + escapeHtml(t.title) + '">';
      html += '</li>';
      var temp = document.createElement('div');
      temp.innerHTML = html;
      li = temp.firstElementChild;
    }
    fragment.appendChild(li);
  }
  // Remove stale li elements that no longer have a matching todo
  for (var staleId in existing) {
    var stale = existing[staleId];
    if (stale.parentNode) stale.parentNode.removeChild(stale);
  }
  // Replace children in one operation
  todoList.innerHTML = '';
  todoList.appendChild(fragment);

