When('I reload the app', function () {
  // Dispose and reload — simulate page reload by creating a fresh window/app.
  // We keep current localStorage (which persists across page reloads in a real browser).
  const stored = {};
  for (let i = 0; i < this.localStorage.length; i++) {
    const key = this.localStorage.key(i);
    stored[key] = this.localStorage.getItem(key);
  }
  const currentHash = this.window.location.hash;
  // Dispose (sets this.window to undefined)
  this.disposeApp();
  // Load the app — create a fresh window
  this.loadApp();
  // Restore hash and localStorage after the fresh window is created
  this.window.location.hash = currentHash;
  for (const [key, val] of Object.entries(stored)) {
    this.localStorage.setItem(key, val);
  }
  // Dispatch hashchange — app re-reads localStorage and re-renders
  this.window.dispatchEvent(new this.window.Event('hashchange'));
});

